import math
from abc import ABC, abstractmethod


class Shape(ABC):
    @abstractmethod
    def area(self) -> float:
        ...


class Circle(Shape):
    def __init__(self, radius: float) -> None:
        self.radius = radius

    def area(self) -> float:
        return math.pi * self.radius ** 2


class Square(Shape):
    def __init__(self, side: float) -> None:
        self.side = side

    def area(self) -> float:
        return self.side ** 2


def total_area(shapes: list[Shape]) -> float:
    return sum(shape.area() for shape in shapes)


n = int(input())
shapes: list[Shape] = []
for _ in range(n):
    kind, size = input().split()
    if kind == "circle":
        shapes.append(Circle(float(size)))
    else:
        shapes.append(Square(float(size)))

for shape in shapes:
    print(f"{shape.area():.2f}")
print(f"Total: {total_area(shapes):.2f}")

